<script>
function setPg(p){var b=document.getElementById('pgbar');if(b)b.style.width=Math.min(100,Number(p))+'%';}
function eH(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function updateProgress(pct,cur,tot,elapsed,eta){
  setPg(pct);document.title='↑ '+Number(pct).toFixed(1)+'%';
  var el=document.getElementById('progress');
  if(el)el.innerHTML=Number(pct).toFixed(2)+'% &mdash; '+eH(cur)+' / '+eH(tot)+'<br><small>Elapsed: '+eH(elapsed)+(eta?' &middot; ETA: '+eH(eta):'')+'</small>';
}
function appendStatus(html){var c=document.getElementById('statuses');if(c)c.insertAdjacentHTML('beforeend','<div class="status-line">'+html+'</div>');}
function _esc(s){var d=document.createElement('div');d.textContent=s;return d.innerHTML;}
function _cp(t){var a=document.createElement('textarea');a.value=t;a.style.cssText='position:fixed;opacity:0';document.body.appendChild(a);a.select();try{document.execCommand('copy');}catch(e){}document.body.removeChild(a);}
function showToast(msg){var t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._ti);t._ti=setTimeout(function(){t.classList.remove('show');},2200);}
function copyText(text,btn){
  var done=function(){showToast('Copied!');if(btn){btn.classList.add('ok');var o=btn.textContent;btn.textContent='✓';setTimeout(function(){btn.textContent=o;btn.classList.remove('ok');},1500);}};
  if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(text).then(done,function(){_cp(text);done();});
  else{_cp(text);done();}
}
function openModal(id){document.getElementById(id).classList.add('open');document.body.style.overflow='hidden';}
function closeModal(id){document.getElementById(id).classList.remove('open');document.body.style.overflow='';}
function openInfoModal(){
  openModal('modal-info');
  document.getElementById('info-content').innerHTML='<div style="text-align:center;padding:2rem;color:var(--t2)">Loading…</div>';
  fetch('',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'_a=info'})
    .then(function(r){return r.json();})
    .then(function(d){
      var h='<div class="info-grid">';
      [{k:'php',l:'PHP Environment'},{k:'server',l:'Server / Host'}].forEach(function(s){
        h+='<div class="info-panel"><h4>'+s.l+'</h4><table>';
        Object.keys(d[s.k]).forEach(function(k){h+='<tr><td>'+_esc(k)+'</td><td>'+_esc(String(d[s.k][k]))+'</td></tr>';});
        h+='</table></div>';
      });
      h+='</div>';
      document.getElementById('info-content').innerHTML=h;
    });
}
var fbCwd='__ROOT__';
function openFileBrowser(){openModal('modal-fb');fbLoad('__ROOT__');}
function fbLoad(path){
  fbCwd=path;
  document.getElementById('fb-loading').style.display='block';
  document.getElementById('fb-content').style.display='none';
  var fd=new FormData();fd.append('_a','ls');fd.append('_p',path);
  fetch('',{method:'POST',body:fd})
    .then(function(r){return r.json();})
    .then(function(d){fbRender(d);document.getElementById('fb-loading').style.display='none';document.getElementById('fb-content').style.display='block';})
    .catch(function(){document.getElementById('fb-loading').innerHTML='<span style="color:var(--rd)">Failed to load directory</span>';});
}
function fbRender(d){
  if(!d.ok){document.getElementById('fb-tbl-wrap').innerHTML='<div class="fb-empty">'+_esc(d.msg||'Error')+'</div>';return;}
  var crumbs='<span class="fb-crumb" onclick="fbLoad(\'__ROOT__\')">🏠 root</span>';
  if(d.breadcrumbs){d.breadcrumbs.forEach(function(b){crumbs+='<span class="fb-sep"> / </span><span class="fb-crumb" onclick="fbLoad('+JSON.stringify(b.path)+')">'+_esc(b.name)+'</span>';});}
  document.getElementById('fb-path').innerHTML=crumbs;
  var h='<table class="fb-tbl"><thead><tr><th style="width:2rem"><input type="checkbox" id="fb-all" onchange="fbSelAll(this)"></th><th>Name</th><th>Size</th><th>Modified</th><th style="text-align:right">Actions</th></tr></thead><tbody>';
  if(d.parent!==null&&d.parent!==undefined){
    var pp=d.parent||'__ROOT__';
    h+='<tr><td></td><td colspan="3"><span class="fb-dn" onclick="fbLoad('+JSON.stringify(pp)+')">📂 ..</span></td><td></td></tr>';
  }
  if(!d.items||!d.items.length){h+='<tr><td colspan="5" class="fb-empty">Empty directory</td></tr>';}
  else{
    d.items.forEach(function(item){
      var isDir=item.type==='dir';
      var nm=isDir?'<span class="fb-dn" onclick="fbLoad('+JSON.stringify(item.path)+')">📂 '+_esc(item.name)+'</span>':'<span class="fb-fn">📄 '+_esc(item.name)+'</span>';
      var urlAttr=(item.url||'').replace(/"/g,'&quot;');
      var pathAttr=item.path.replace(/"/g,'&quot;');
      h+='<tr data-path="'+pathAttr+'" data-url="'+urlAttr+'">'
        +'<td><input type="checkbox" class="fb-chk" onchange="fbChkChg()" value="'+pathAttr+'"></td>'
        +'<td>'+nm+'</td>'
        +'<td class="fb-sz">'+(isDir?'&mdash;':_esc(item.size))+'</td>'
        +'<td class="fb-mt">'+_esc(item.mtime)+'</td>'
        +'<td class="fb-acts">'
        +(item.url?'<button class="btn btn-g btn-sm btn-icon" title="Copy URL" onclick="copyText('+JSON.stringify(item.url)+')">&#128203;</button>':'')
        +'<button class="btn btn-d btn-sm btn-icon" title="Delete" onclick="fbDel('+JSON.stringify(item.path)+','+JSON.stringify(item.name)+')">&#10005;</button>'
        +'</td></tr>';
    });
  }
  h+='</tbody></table>';
  document.getElementById('fb-tbl-wrap').innerHTML=h;
  document.getElementById('fb-bulk').classList.remove('show');
}
function fbSelAll(cb){document.querySelectorAll('.fb-chk').forEach(function(c){c.checked=cb.checked;});fbChkChg();}
function fbChkChg(){
  var cc=document.querySelectorAll('.fb-chk:checked');
  var bulk=document.getElementById('fb-bulk');
  if(cc.length>0){bulk.classList.add('show');document.getElementById('fb-sel-n').textContent=cc.length+' selected';}
  else bulk.classList.remove('show');
}
function fbCopySelected(){
  var urls=[];
  document.querySelectorAll('.fb-chk:checked').forEach(function(c){var r=c.closest('tr');if(r&&r.dataset.url)urls.push(r.dataset.url);});
  if(urls.length)copyText(urls.join('\n'));else showToast('No web URLs available for selected items');
}
function fbDelSelected(){
  var paths=[];document.querySelectorAll('.fb-chk:checked').forEach(function(c){paths.push(c.value);});
  if(!paths.length)return;
  if(!confirm('Delete '+paths.length+' item(s)?\nThis cannot be undone.'))return;
  var done=0,total=paths.length;
  paths.forEach(function(p){var fd=new FormData();fd.append('_a','del');fd.append('_p',p);fetch('',{method:'POST',body:fd}).then(function(r){return r.json();}).then(function(){done++;if(done===total){showToast('Deleted '+total+' item(s)');fbLoad(fbCwd);}});});
}
function fbDel(path,name){
  if(!confirm('Delete "'+name+'"?\nThis cannot be undone.'))return;
  var fd=new FormData();fd.append('_a','del');fd.append('_p',path);
  fetch('',{method:'POST',body:fd}).then(function(r){return r.json();}).then(function(d){if(d.ok){showToast('Deleted: '+name);fbLoad(fbCwd);}else showToast('Error: '+(d.msg||'failed'));});
}
